'use strict';
// Bundle src/adventure/* into one ES module the browser can import.
//
// Same trick as tools/recovery-kit/build.js: each file keeps its own scope and its own `module`
// object, and a tiny registry resolves require() between them. Flattening them into one shared
// scope would be shorter and wrong: three of these files define a local `draw()` with different
// semantics, and the last one loaded would silently win. That exact collision has already cost this
// project a whole afternoon once.
//
// The build refuses to write a bundle that does not parse, because a bundle that does not parse is
// a page where every button quietly does nothing.

const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', '..', 'src', 'adventure');
const OUT = path.join(__dirname, '..', '..', 'web', 'adventure-core.js');

// Load order matters only in that every dependency must be registered before it is required at
// call time; the registry is lazy, so the list is just every file.
const FILES = ['counts.gen', 'pool', 'faces', 'bodies', 'backgrounds', 'runes', 'combat', 'vivarium', 'hunt'];

function isolate(name, code) {
  return `registry[${JSON.stringify(name)}] = function (module, exports, require) {\n${code}\n};\n`;
}

function build() {
  let out = `// Generated by tools/adventure/bundle.js. Do not edit: edit src/adventure/*.js and rebuild.
// The game rules live in one place and are shared by the browser and by node, so a fight the
// player sees is the same fight a server can recompute.

const registry = {};
const cache = {};
function require(id) {
  const name = String(id).replace(/^\\.\\//, '');
  if (cache[name]) return cache[name].exports;
  const factory = registry[name];
  if (!factory) throw new Error('adventure-core: no module ' + name);
  const module = { exports: {} };
  cache[name] = module;
  factory(module, module.exports, require);
  return module.exports;
}

`;

  for (const f of FILES) {
    const code = fs.readFileSync(path.join(SRC, f + '.js'), 'utf8');
    out += isolate(f, code);
  }

  out += `
export const pool = require('pool');
export const faces = require('faces');
export const bodies = require('bodies');
export const backgrounds = require('backgrounds');
export const runes = require('runes');
export const combat = require('combat');
export const vivarium = require('vivarium');
export const hunt = require('hunt');
`;

  // A bundle that does not parse must never reach the page.
  try {
    new Function(out.replace(/^export const .*$/gm, '').replace(/\bexport\b/g, ''));
  } catch (e) {
    throw new Error('bundle does not parse: ' + e.message);
  }

  fs.writeFileSync(OUT, out);
  return { bytes: out.length, modules: FILES.length };
}

if (require.main === module) {
  const r = build();
  console.log(`web/adventure-core.js  ${r.modules} modules, ${(r.bytes / 1024).toFixed(1)} KB`);
}
module.exports = { build };
